import * as React from 'react';
import * as StickyParallaxScrollPrimitive from '@exhuma/core';
import { clsx } from 'clsx';

export interface StickyParallaxScrollProps extends React.ComponentPropsWithoutRef<typeof StickyParallaxScrollPrimitive.StickyParallaxScroll> {
  className?: string;
}

export const StickyParallaxScroll = React.forwardRef<HTMLDivElement, StickyParallaxScrollProps>(
  ({ className, children, ...props }, ref) => (
    <StickyParallaxScrollPrimitive.StickyParallaxScroll
      ref={ref}
      className={clsx(
        'relative w-full overflow-hidden',
        className
      )}
      {...props}
    >
      {children}
    </StickyParallaxScrollPrimitive.StickyParallaxScroll>
  )
);
StickyParallaxScroll.displayName = 'StickyParallaxScroll';

